create function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table environments (id uuid primary key default gen_random_uuid(), name text not null unique, owner text not null, engine text not null default 'postgresql' check(engine='postgresql'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table changes (id uuid primary key default gen_random_uuid(), code text not null unique, title text not null, environment_id uuid not null references environments, owner text not null, due_date date not null, risk text not null check(risk in ('normal','high')), version integer not null default 1 check(version>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table versions (id uuid primary key default gen_random_uuid(), change_id uuid not null references changes, version integer not null, digest text not null check(length(digest)=64), specification jsonb not null, reason text not null, author text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(change_id,version));
create table rehearsals (id uuid primary key default gen_random_uuid(), version_id uuid not null references versions, passed boolean not null, result jsonb not null, operator text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table approvals (id uuid primary key default gen_random_uuid(), version_id uuid not null references versions, rehearsal_id uuid not null references rehearsals, reviewer text not null, evidence text not null, decision text not null check(decision in ('approve','reject')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table deployments (id uuid primary key default gen_random_uuid(), version_id uuid not null references versions, approval_id uuid not null references approvals, outcome text not null check(outcome in ('succeeded','failed','rolled-back')), evidence text not null, operator text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table legacy_history (id uuid primary key default gen_random_uuid(), environment_id uuid not null references environments, change_key text not null, author text not null, filename text not null, executed_at text not null, order_executed integer not null check(order_executed>=0), execution_type text not null, checksum text, source_row jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(environment_id,change_key,author,filename));
create table notes (id uuid primary key default gen_random_uuid(), change_id uuid not null references changes, note text not null, operator text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table audit (id uuid primary key default gen_random_uuid(), action text not null, entity_id uuid, operator text not null, details jsonb not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['environments','changes','versions','rehearsals','approvals','deployments','legacy_history','notes','audit'] loop execute format('create trigger touch before update on %I for each row execute function touch_updated_at()',t); execute format('alter table %I enable row level security',t); execute format('revoke all on %I from public',t); end loop; end $$;
create view release_queue as
select c.id,c.code,c.title,e.name as environment,c.owner,c.due_date,c.risk,c.version,v.id as version_id,
r.passed as rehearsal_passed,r.created_at as rehearsed_at,a.decision,a.reviewer,d.outcome,
case when d.outcome is not null then d.outcome when a.decision='reject' then 'rejected' when r.passed is true and a.decision='approve' and a.rehearsal_id=r.id then 'ready' when r.passed is false then 'rehearsal failed' when r.passed is true then 'needs approval' else 'needs rehearsal' end as state
from changes c join environments e on e.id=c.environment_id join versions v on v.change_id=c.id and v.version=c.version
left join lateral (select * from rehearsals where version_id=v.id order by created_at desc,id desc limit 1) r on true
left join lateral (select * from approvals where version_id=v.id order by created_at desc,id desc limit 1) a on true
left join lateral (select * from deployments where version_id=v.id order by created_at desc,id desc limit 1) d on true;
create view attention as select code,title,environment,owner,due_date,state from release_queue where state not in ('succeeded','rolled-back') and (due_date<current_date or state in ('rehearsal failed','failed','rejected'));
create view compliance_gaps as
select code,'LOCAL_TEST' as rule,'No passing current-version rehearsal' as finding from release_queue where rehearsal_passed is distinct from true
union all select code,'LOCAL_REVIEW','Independent approval for latest rehearsal missing' from release_queue where state in ('needs rehearsal','needs approval','rehearsal failed','rejected')
union all select code,'LOCAL_RECOVERY','Failed deployment has no later recorded recovery' from release_queue where outcome='failed';
revoke all on release_queue,attention,compliance_gaps from public;
